// ===== OPTIONAL ADVANCED SETTINGS (the defaults work for most people) =====
return [{ json: {
  // Only used to recognise playlists created by earlier versions ('[Curator] name'). New playlists get plain names.
  playlistPrefix: '[Curator] ',
  // Name of the playlist that collects songs the sorter could not place.
  fallbackName: 'Unsorted songs',
  playlistsPublic: false,
  defaultMaxSongs: 10000
} }];

const total = $input.first().json.total || 0;
const pages = Math.max(1, Math.ceil(total / 50));
return Array.from({ length: pages }, (_, p) => ({ json: { offset: p * 50 } }));

const s = $('Settings').first().json;
const input = $('When Executed by Another Workflow').first().json;
const me = $('Get Me').first().json;
const rows = $('Registry Snapshot').first().json.rows || [];
const reg = new Map(rows.map(r => [r.playlistId, r]));
const decode = t => String(t || '').replace(/&quot;/g, '"').replace(/&#x27;/g, "'").replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
const prefix = s.playlistPrefix;
const legacyUnsortedName = prefix + 'unsorted';
const unsortedCandidates = [];
const categories = [];
const others = [];
const toRegister = [];
const seenIds = new Set();
const usedNames = new Set();
let followed = 0;
let totalPlaylists = 0;
for (const page of $input.all()) {
  for (const p of (page.json.items || [])) {
    if (!p) continue;
    totalPlaylists++;
    const url = p.external_urls && p.external_urls.spotify;
    const tracks = p.items && typeof p.items.total === 'number' ? p.items.total : null;
    if (!p.owner || p.owner.id !== me.id) { followed++; continue; }
    seenIds.add(p.id);
    const rawDesc = decode(p.description);
    const name = String(p.name || '');
    const hasPrefix = name.startsWith(prefix);
    const clean = rawDesc.replace(/\[curator:unsorted\]|\[curator\]|\[default\]/gi, '').replace(/\s+/g, ' ').trim();
    const r = reg.get(p.id);
    let role = null;
    let rule = '';
    let isDefault = false;
    if (r) { role = r.role === 'unsorted' ? 'unsorted' : 'category'; rule = r.rule; isDefault = r.isDefault; }
    else if ((hasPrefix && name === legacyUnsortedName) || /\[curator:unsorted\]/i.test(rawDesc)) { role = 'unsorted'; }
    else if (hasPrefix || /\[curator\]/i.test(rawDesc)) { role = 'category'; rule = clean; isDefault = /\[default\]/i.test(rawDesc); }
    if (role === 'unsorted') { unsortedCandidates.push({ id: p.id, name, url, tracks, registered: !!r }); continue; }
    if (role === 'category') {
      const display = hasPrefix ? name.slice(prefix.length) : name;
      let unique = display;
      let n = 2;
      while (usedNames.has(unique.toLowerCase())) { unique = display + ' (' + (n++) + ')'; }
      usedNames.add(unique.toLowerCase());
      categories.push({ name: unique, playlistName: name, id: p.id, url, tracks, criteria: rule, isDefault });
      if (!r) toRegister.push({ playlistId: p.id, role: 'category', rule: rule.slice(0, 270), isDefault: String(isDefault) });
      continue;
    }
    others.push({ name, id: p.id, url, tracks, description: clean });
  }
}
const chosen = unsortedCandidates.find(c => c.registered) || unsortedCandidates[0] || null;
const fallback = chosen ? { id: chosen.id, name: chosen.name, url: chosen.url, tracks: chosen.tracks } : null;
if (chosen && !chosen.registered) toRegister.push({ playlistId: chosen.id, role: 'unsorted', rule: '', isDefault: 'false' });
const missing = rows.filter(r => !seenIds.has(r.playlistId)).map(r => ({ playlistId: r.playlistId, role: r.role, rule: r.rule }));
return [{ json: { action: String(input.action || '').toLowerCase(), name: input.name, description: input.description, isDefault: !!input.isDefault, role: String(input.role || '').toLowerCase(), maxSongs: input.maxSongs, newCategories: input.newCategories, categories, fallback, others, followed, totalPlaylists, toRegister, missing } }];

const d = $input.first().json;
const categories = d.categories.map(c => ({ name: c.name, rule: c.criteria || '(no rule yet)', catchAll: c.isDefault, songsInPlaylist: c.tracks, link: c.url }));
const others = d.others.map(o => ({ name: o.name, songs: o.tracks, link: o.url }));
const unsorted = d.fallback ? { name: d.fallback.name, songs: d.fallback.tracks, link: d.fallback.url } : null;
let message = categories.length
  ? 'These are the current sorting categories.'
  : 'No sorting categories are set up yet. The user has ' + others.length + ' other playlists of their own (see otherOwnPlaylists); they can be adopted as categories or left untouched.';
const missingCount = (d.missing || []).length;
if (missingCount) message += ' ' + missingCount + ' registered playlist(s) no longer exist in Spotify (deleted or unfollowed) and are ignored.';
return [{ json: { totalPlaylistsOnAccount: d.totalPlaylists, ownPlaylists: categories.length + (unsorted ? 1 : 0) + others.length, followedPlaylists: d.followed, categories, unsortedPlaylist: unsorted, otherOwnPlaylists: others, message } }];

const s = $('Settings').first().json;
const d = $input.first().json;
const fail = message => [{ json: { toCreate: [], notes: [], error: true, message, anyToCreate: false } }];
let wanted = [];
if (d.newCategories) {
  try {
    const parsed = typeof d.newCategories === 'string' ? JSON.parse(d.newCategories) : d.newCategories;
    wanted = Array.isArray(parsed) ? parsed : [parsed];
  } catch (e) {
    return fail('Could not read the category list. Pass a JSON array like [{"name":"workout","description":"...","isDefault":false}].');
  }
} else if (d.name) {
  wanted = [{ name: d.name, description: d.description, isDefault: d.isDefault }];
}
wanted = wanted.filter(w => w && String(w.name || '').trim());
if (!wanted.length) return fail('At least one category with a name is required.');
const notes = [];
const toCreate = [];
const seen = new Set(d.categories.map(c => c.name.toLowerCase()));
const ownNames = new Set(d.others.map(o => String(o.name).trim().toLowerCase()));
for (const w of wanted) {
  const name = String(w.name).trim();
  if (seen.has(name.toLowerCase())) {
    notes.push('Category "' + name + '" already exists, so it was not created again.');
    continue;
  }
  if (ownNames.has(name.toLowerCase())) {
    notes.push('You already have a playlist named "' + name + '", so it was not created again. Adopt it instead if it should be a category.');
    continue;
  }
  seen.add(name.toLowerCase());
  const rule = String(w.description || '').replace(/\[(curator:unsorted|curator|default)\]/gi, '').trim().slice(0, 270);
  const isDefault = w.isDefault === true || String(w.isDefault).toLowerCase() === 'true';
  toCreate.push({ fullName: name, description: rule, public: !!s.playlistsPublic, role: 'category', rule, isDefault });
}
if (!d.fallback) {
  toCreate.push({ fullName: s.fallbackName, description: 'Songs the sorter could not place. Re-sorted on request.', public: !!s.playlistsPublic, role: 'unsorted', rule: '', isDefault: false });
}
return [{ json: { toCreate, notes, anyToCreate: toCreate.length > 0 } }];

const p = $('Plan Creation').first().json;
const created = $('Create Playlist').isExecuted ? $('Create Playlist').all().map(i => i.json) : [];
return [{ json: {
  created: created.map(c => ({ name: c.name, link: c.external_urls && c.external_urls.spotify })),
  notes: p.notes || [],
  message: p.error ? p.message : (created.length ? 'Created ' + created.length + ' playlist(s).' : 'Nothing new to create.')
} }];

const s = $('Settings').first().json;
const d = $('Load Categories').first().json;
const fail = message => [{ json: { ok: false, message, action: d.action } }];
if (!d.categories.length) return fail('No categories exist yet. Create a category or adopt one of the existing playlists first.');
if (!d.fallback) return fail('There is no unsorted playlist yet. Create any new category (this also creates the unsorted playlist) or adopt an existing playlist with role unsorted.');
const playlists = d.categories.map(c => ({ key: c.name, id: c.id }));
playlists.push({ key: '__fallback', id: d.fallback.id });
const map = {};
playlists.forEach(p => { map[p.key] = p.id; });
const maxSongs = Math.max(1, Math.floor(Number(d.maxSongs) || s.defaultMaxSongs));
return [{ json: { ok: true, action: d.action, playlists, map, maxSongs } }];

const plan = $('Plan Count Requests').all().map(i => i.json);
const counts = $input.all();
const totalOf = idx => (counts[idx] && counts[idx].json.items ? counts[idx].json.items.total : 0);
const expectedTotal = plan.reduce((a, _, idx) => a + totalOf(idx), 0);
const out = [];
plan.forEach((p, idx) => {
  const pages = Math.max(1, Math.ceil(totalOf(idx) / 50));
  for (let pg = 0; pg < pages; pg++) {
    out.push({ json: { key: p.key, id: p.id, offset: pg * 50, expectedTotal } });
  }
});
return out;

const plan = $('Plan Pages').all().map(i => i.json);
const pages = $input.all();
const known = new Set();
const playlistTracks = {};
let rawCount = 0;
pages.forEach((p, idx) => {
  const meta = plan[idx] || {};
  const entries = (p.json && p.json.items) || [];
  for (const e of entries) {
    rawCount++;
    const t = e && (e.item || e.track);
    if (t && t.uri) {
      known.add(t.uri);
      if (t.id && t.artists && t.artists[0]) {
        (playlistTracks[meta.key] = playlistTracks[meta.key] || []).push({ id: t.id, uri: t.uri, name: t.name, artistId: t.artists[0].id, artistName: t.artists[0].name || 'Unknown', album: (t.album && t.album.name) || '', year: String((t.album && t.album.release_date) || '').slice(0, 4), addedAt: e.added_at || '' });
      }
    }
  }
});
const expected = plan.length ? plan[0].expectedTotal : 0;
if (rawCount !== expected) {
  throw new Error('Known-set mismatch: fetched ' + rawCount + ' playlist entries but playlists report ' + expected + '. Aborting to avoid duplicates.');
}
return [{ json: { known: [...known], playlistTracks, knownCount: known.size } }];

const total = $input.first().json.total || 0;
const pages = Math.max(1, Math.ceil(total / 50));
return Array.from({ length: pages }, (_, p) => ({ json: { offset: p * 50 } }));

const pre = $('Preflight').first().json;
const known = new Set($('Build Known Set').first().json.known);
const seen = new Set();
const unknown = [];
for (const page of $input.all()) {
  for (const it of ((page.json && page.json.items) || [])) {
    const t = it && it.track;
    if (!t || !t.id || !t.uri || !t.artists || !t.artists[0]) continue;
    if (known.has(t.uri) || seen.has(t.uri)) continue;
    seen.add(t.uri);
    unknown.push({ id: t.id, uri: t.uri, name: t.name, artistId: t.artists[0].id, artistName: t.artists[0].name || 'Unknown', album: (t.album && t.album.name) || '', year: String((t.album && t.album.release_date) || '').slice(0, 4) });
  }
}
const queue = unknown.slice(0, pre.maxSongs);
return [{ json: { queue, totalUnknown: unknown.length, remaining: unknown.length - queue.length } }];

const q = $('Find Unknown Songs').first().json.queue;
const i = $('Batch Index').first().json.index;
const tracks = q.slice(i * 50, i * 50 + 50);
const artistIds = [...new Set(tracks.map(t => t.artistId).filter(Boolean))];
return [{ json: { tracks, artistIds, hasMore: (i + 1) * 50 < q.length } }];

const cats = $('Load Categories').first().json.categories;
const names = cats.map(c => c.name);
const def = (cats.find(c => c.isDefault) || cats[cats.length - 1]).name;
const catText = cats.map(c => `- "${c.name}": ${c.criteria || 'songs that fit the name "' + c.name + '"'}`).join('\n');

const tracks = $('Take Batch').first().json.tracks;
const enriched = tracks.map(t => ({ id: t.id, uri: t.uri, name: t.name, artist: t.artistName, album: t.album || '', year: t.year || '' }));

const listText = enriched
  .map((t, i) => `${i + 1}. "${t.name}" by ${t.artist}` + (t.album ? ` | album: ${t.album}${t.year ? ' (' + t.year + ')' : ''}` : ''))
  .join('\n');
const example = JSON.stringify([{ n: 1, genre: 'short genre label', category: names[0] }, { n: 2, genre: 'short genre label', category: names[names.length - 1] }]);

const prompt = `You are a music playlist sorter with deep knowledge of music. Spotify genre data is not available, so use your own knowledge of each artist and song (and the album and year) to decide.

Categories:
${catText}

For each track, first decide the song's most likely genre or style from your knowledge of the artist and the song, then choose the category whose rule best matches that genre. Only choose "${def}" when the track really does not match another category's rule; do not use it as a shortcut for songs you are unsure about - think about the artist's main genre first.

Tracks (numbered list):
${listText}

Respond with ONLY a raw JSON array of exactly ${enriched.length} objects, one for each track, no markdown formatting, no commentary. Each object has "n" (the track's number from the list above, 1 to ${enriched.length}), "genre" (a short genre label you decided on) and "category" (one of the category names exactly as written above). Include every track number exactly once. Example format:
${example}`;

return [{ json: { prompt, tracks: enriched } }];

const cats = $('Load Categories').first().json.categories;
const valid = cats.map(c => c.name);
const lookup = {};
valid.forEach(n => { lookup[n.toLowerCase()] = n; });

const first = $input.first().json;
const raw = (first.text ?? first.output ?? (first.response && first.response.text) ?? '').toString();
let parsed = [];
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
  if (!Array.isArray(parsed)) parsed = [];
} catch (e) {
  parsed = [];
}

const tracks = $('Build Prompt').first().json.tracks;

// Match answers to songs by the track number the model returned. Fall back to position only when the count is exactly right and no number is usable.
const byIndex = new Map();
parsed.forEach((item, pos) => {
  if (!item || typeof item !== 'object') return;
  let n = Number(item.n);
  if (!Number.isInteger(n) || n < 1 || n > tracks.length) {
    if (parsed.length === tracks.length) n = pos + 1; else return;
  }
  if (!byIndex.has(n)) byIndex.set(n, item);
});

const groups = {};
valid.forEach(n => { groups[n] = { uris: [], songs: [] }; });
groups['__fallback'] = { uris: [], songs: [] };
let unreadable = 0;

tracks.forEach((t, i) => {
  const item = byIndex.get(i + 1);
  const cat = item ? item.category : undefined;
  const genre = item ? String(item.genre || '') : '';
  const canon = typeof cat === 'string' ? lookup[cat.trim().toLowerCase()] : undefined;
  if (!canon) unreadable++;
  const g = canon ? groups[canon] : groups['__fallback'];
  g.uris.push(t.uri);
  g.songs.push({ name: t.name, artist: t.artist, genre });
});

if (unreadable > 0) {
  console.log('Could not read an answer for ' + unreadable + ' of ' + tracks.length + ' songs (model returned ' + parsed.length + ' entries) - those go to unsorted');
}

const output = [];
for (const [category, g] of Object.entries(groups)) {
  if (g.uris.length > 0) {
    output.push({ json: { category, uris: g.uris, songs: g.songs } });
  }
}
return output;

const pre = $('Preflight').first().json;
const d = $('Load Categories').first().json;
const all = $('Build Known Set').first().json.playlistTracks || {};
let sourceKey = '__fallback';
if (pre.action === 'recheck') {
  const wanted = String(d.name || '').trim().toLowerCase();
  const cat = wanted ? d.categories.find(c => c.name.toLowerCase() === wanted) : (d.categories.find(c => c.isDefault) || null);
  if (!cat) return [{ json: { tracks: [], sourceKey: null, totalInSource: 0, error: wanted ? 'No category named "' + d.name + '".' : 'Say which category to re-check.' } }];
  sourceKey = cat.name;
}
const pool = (all[sourceKey] || []).slice().sort((a, b) => String(b.addedAt || '').localeCompare(String(a.addedAt || '')));
const limit = pre.action === 'retry' ? 100 : Math.min(pre.maxSongs, 100);
const tracks = pool.slice(0, limit);
return [{ json: { tracks, sourceKey, totalInSource: pool.length } }];

const cats = $('Load Categories').first().json.categories;
const names = cats.map(c => c.name);
const def = (cats.find(c => c.isDefault) || cats[cats.length - 1]).name;
const catText = cats.map(c => `- "${c.name}": ${c.criteria || 'songs that fit the name "' + c.name + '"'}`).join('\n');

const tracks = $('Prepare Retry Batch').first().json.tracks;
const enriched = tracks.map(t => ({ id: t.id, uri: t.uri, name: t.name, artist: t.artistName, album: t.album || '', year: t.year || '' }));

const listText = enriched
  .map((t, i) => `${i + 1}. "${t.name}" by ${t.artist}` + (t.album ? ` | album: ${t.album}${t.year ? ' (' + t.year + ')' : ''}` : ''))
  .join('\n');
const example = JSON.stringify([{ n: 1, genre: 'short genre label', category: names[0] }, { n: 2, genre: 'short genre label', category: names[names.length - 1] }]);

const prompt = `You are a music playlist sorter with deep knowledge of music, re-checking songs that may have been placed in the wrong playlist. Spotify genre data is not available, so use your own knowledge of each artist and song (and the album and year) to decide.

Categories:
${catText}

For each track, first decide the song's most likely genre or style from your knowledge of the artist and the song, then choose the category whose rule best matches that genre. Only choose "${def}" when the track really does not match another category's rule.

Tracks (numbered list):
${listText}

Respond with ONLY a raw JSON array of exactly ${enriched.length} objects, one for each track, no markdown formatting, no commentary. Each object has "n" (the track's number from the list above, 1 to ${enriched.length}), "genre" (a short genre label you decided on) and "category" (one of the category names exactly as written above). Include every track number exactly once. Example format:
${example}`;

return [{ json: { prompt, tracks: enriched } }];

const cats = $('Load Categories').first().json.categories;
const valid = cats.map(c => c.name);
const lookup = {};
valid.forEach(n => { lookup[n.toLowerCase()] = n; });

const first = $input.first().json;
const raw = (first.text ?? first.output ?? (first.response && first.response.text) ?? '').toString();
let parsed = [];
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
  if (!Array.isArray(parsed)) parsed = [];
} catch (e) {
  parsed = [];
}

const prep = $('Prepare Retry Batch').first().json;
const tracks = $('Build Retry Prompt').first().json.tracks;

const byIndex = new Map();
parsed.forEach((item, pos) => {
  if (!item || typeof item !== 'object') return;
  let n = Number(item.n);
  if (!Number.isInteger(n) || n < 1 || n > tracks.length) {
    if (parsed.length === tracks.length) n = pos + 1; else return;
  }
  if (!byIndex.has(n)) byIndex.set(n, item);
});

const groups = {};
valid.forEach(n => { groups[n] = []; });
const allResolved = [];
const movedSongs = [];
let unchanged = 0;
let unreadable = 0;

tracks.forEach((t, i) => {
  const item = byIndex.get(i + 1);
  const cat = item ? item.category : undefined;
  const genre = item ? String(item.genre || '') : '';
  const canon = typeof cat === 'string' ? lookup[cat.trim().toLowerCase()] : undefined;
  if (!canon) { unreadable++; unchanged++; return; }
  if (canon === prep.sourceKey) { unchanged++; return; }
  groups[canon].push(t.uri);
  allResolved.push(t.uri);
  movedSongs.push(t.artist + ' - ' + t.name + ' (' + genre + ') -> ' + canon);
});

const adds = [];
for (const [category, uris] of Object.entries(groups)) {
  if (uris.length > 0) adds.push({ category, uris });
}
return [{ json: { adds, allResolved, anyResolved: allResolved.length > 0, unchanged, unreadable, movedSongs: movedSongs.slice(0, 30), sourceKey: prep.sourceKey } }];

const pre = $('Preflight').first().json;
if (!pre.ok) return [{ json: { status: 'cannot_run', message: pre.message } }];
if (pre.action === 'retry' || pre.action === 'recheck') {
  const prep = $('Prepare Retry Batch').isExecuted ? $('Prepare Retry Batch').first().json : null;
  if (!prep || prep.tracks.length === 0) return [{ json: { status: 'nothing_to_do', message: prep && prep.error ? prep.error : 'There are no songs to re-check in that playlist.' } }];
  const res = $('Parse Retry Results').isExecuted ? $('Parse Retry Results').first().json : null;
  const moved = res ? res.allResolved.length : 0;
  const source = prep.sourceKey === '__fallback' ? 'unsorted' : prep.sourceKey;
  return [{ json: { status: 'done', checked: prep.tracks.length, source, moved, unchanged: res ? res.unchanged : prep.tracks.length, unreadable: res ? (res.unreadable || 0) : 0, stillInSource: prep.totalInSource - moved, movedSongs: res ? res.movedSongs : [], message: 'Checked ' + prep.tracks.length + ' songs from "' + source + '" and moved ' + moved + '.' + ((res && res.unreadable) ? ' ' + res.unreadable + ' of the model answers could not be read, so those songs were left where they are; running it again usually fixes that.' : '') } }];
}
const fu = $('Find Unknown Songs').isExecuted ? $('Find Unknown Songs').first().json : null;
if (!fu || fu.queue.length === 0) return [{ json: { status: 'up_to_date', message: 'There are no new liked songs to sort.' } }];
const counts = {};
const songs = {};
for (let r = 0; r < 500; r++) {
  let items;
  try { items = $('Parse & Group by Category').all(0, r); } catch (e) { break; }
  if (!items || !items.length) break;
  for (const it of items) {
    const c = it.json.category === '__fallback' ? 'unsorted' : it.json.category;
    counts[c] = (counts[c] || 0) + it.json.uris.length;
    songs[c] = (songs[c] || []).concat(it.json.songs || []);
  }
}
for (const c of Object.keys(songs)) {
  songs[c] = songs[c].slice(0, 15).map(s => s.artist + ' - ' + s.name + (s.genre ? ' (' + s.genre + ')' : ''));
}
return [{ json: { status: 'done', sorted: fu.queue.length, remainingToSort: fu.remaining, perCategory: counts, sampleSongs: songs, message: 'Sorted ' + fu.queue.length + ' songs; ' + fu.remaining + ' liked songs are still unsorted.' } }];

const d = $input.first().json;
const fail = message => [{ json: { ok: false, message } }];
const wanted = String(d.name || '').trim().toLowerCase();
if (!wanted) return fail('Tell me which existing playlist to adopt.');
const role = d.role === 'unsorted' ? 'unsorted' : 'category';
const managed = d.categories.find(c => c.playlistName.toLowerCase() === wanted || c.name.toLowerCase() === wanted) || (d.fallback && d.fallback.name.toLowerCase() === wanted ? d.fallback : null);
if (managed) return fail('"' + (managed.playlistName || managed.name) + '" is already managed by the curator.');
const matches = d.others.filter(o => String(o.name).trim().toLowerCase() === wanted);
if (matches.length === 0) {
  const near = d.others.filter(o => String(o.name).toLowerCase().includes(wanted)).map(o => o.name).slice(0, 5);
  return fail('No playlist of yours is named "' + d.name + '".' + (near.length ? ' Similar names: ' + near.join(', ') + '.' : ''));
}
if (matches.length > 1) return fail('You have ' + matches.length + ' playlists with that name; rename one first so I can tell them apart.');
if (role === 'unsorted' && d.fallback) return fail('An unsorted playlist already exists ("' + d.fallback.name + '").');
const rule = String(d.description || '').replace(/\[(curator:unsorted|curator|default)\]/gi, '').trim().slice(0, 270);
if (role === 'category' && !rule) return fail('Describe which songs belong in this playlist so I can record the rule.');
return [{ json: { ok: true, role, target: { id: matches[0].id, name: matches[0].name, tracks: matches[0].tracks }, rule: role === 'unsorted' ? '' : rule, isDefault: role === 'category' && !!d.isDefault } }];

const p = $('Plan Adoption').first().json;
if (!p.ok) return [{ json: { status: 'not_adopted', message: p.message } }];
return [{ json: { status: 'adopted', playlist: p.target.name, role: p.role, songsAlreadyInPlaylist: p.target.tracks, message: 'Adopted "' + p.target.name + '" as ' + (p.role === 'unsorted' ? 'the unsorted playlist' : 'a category') + '. Its name, description and songs are unchanged, and it can be renamed freely because the curator tracks it by playlist ID.' } }];

const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.playlistId)
  .map(r => ({
    playlistId: String(r.playlistId),
    role: String(r.role || 'category'),
    rule: String(r.rule || ''),
    isDefault: r.isDefault === true || String(r.isDefault).toLowerCase() === 'true'
  }));
return [{ json: { rows } }];
